import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`lead-enrichment`,heroTitle:`Enrich your leads in minutes`,heroSubtitle:`Perplexity Computer researches every contact, fills in missing firmographic data, and delivers enriched profiles — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your leads`,inputFileAccept:`.csv,.xlsx,.xls,.pdf,.doc,.docx`,inputFilePrefill:`Review the uploaded file containing a list of leads. For each lead: (1) Extract all available fields — name, email, company, title, phone, LinkedIn URL, and any other data present. (2) Research each contact and their company across the web to fill in missing fields including job title, company size, industry, headquarters location, LinkedIn profile, annual revenue, funding stage, and tech stack. (3) Verify email addresses and flag any that appear invalid or outdated. (4) Score each lead on completeness before and after enrichment. (5) Identify decision-maker status and buying signals based on recent company news, job changes, and funding events. (6) Deliver a fully enriched spreadsheet with one row per lead showing: all original fields, all enriched fields, completeness score before and after, decision-maker flag, and key buying signals.`,heroOverlaySteps:[`Parsing your lead list and extracting all available contact fields`,`Researching each contact and company across the web for missing data`,`Verifying emails and scoring leads on completeness and buying signals`,`Enriched profiles with firmographic data and lead scores — ready to export`],generatingSteps:[`Parsing the uploaded file to extract contact names, emails, and company data`,`Designing an agent to research each lead across the web for missing firmographic fields`,`Configuring email verification, lead scoring, and buying signal detection`,`Setting up enriched spreadsheet with before/after completeness scores and decision-maker flags`],featureSectionTitle:`From lead list to enriched pipeline`,featureCardTitles:[`Connects to your sales stack`,`Outputs you can sell with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Pipedrive, Notion, Airtable, Slack — Computer plugs into your tools so enriched leads flow straight into your CRM and outreach workflows.`,`Complete contact profiles. Verified emails. Firmographic data — industry, revenue, headcount, funding stage. Decision-maker flags. Buying signal summaries. Before/after completeness scores.`],capabilitySectionTitle:`Your research team, on autopilot`,capabilitySectionSubtitle:`Upload your lead list, step away, come back to fully enriched profiles.`,capabilityCards:[{title:`Contact Enrichment`,description:`Computer can research every lead across the web — filling in job titles, LinkedIn profiles, phone numbers, and verified email addresses.`},{title:`Company Research`,description:`Computer can pull firmographic data for each company — industry, headcount, revenue, funding stage, tech stack, and headquarters location.`},{title:`Buying Signal Detection`,description:`Computer can surface recent funding rounds, leadership changes, hiring surges, and product launches — so you know which leads to prioritize.`},{title:`Connect Your Tools`,description:`Computer can push enriched leads to Pipedrive, Google Sheets, Airtable, Notion, and Slack — build workflows across your entire sales stack.`},{title:`Remember & Improve`,description:`Computer can remember your ideal customer profile, enrichment preferences, and past lists — so every upload builds on what it already knows.`},{title:`Monitor & Refresh`,description:`Computer can re-enrich your leads on a schedule and alert you when contacts change roles, companies raise funding, or emails go stale.`}]});export{t as default};
